questionvariables.text:
fn: rand(3);          /* 0 inverse sine, 1 inverse cosine, 2 inverse tangent */
s: rand([-1,1]);      /* sign of the input */
k: rand([1/6,1/4,1/3]);
/* Design backwards: the principal value first, then the input value from it */
ta: if fn = 1 then (if s = 1 then k*%pi else %pi - k*%pi) else s*k*%pi;
val: if fn = 0 then sin(ta) elseif fn = 1 then cos(ta) else tan(ta);
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Enter a real number, not an expression containing a letter, a variable or i.");
/* Diagnostics, checked pairwise distinct (and distinct from ta+pi/12) for all 18 variants:
   1. another angle with the same ratio, outside the principal range;
   2. the principal value in degrees;
   3. sign error: -ta for inverse sine and tangent; for inverse cosine, -k*pi (the
      odd-function rule wrongly applied, or a negative angle). */
wrong_outofrange: if fn = 0 then (if s = 1 then %pi - k*%pi else %pi + k*%pi)
                  elseif fn = 1 then (if s = 1 then 2*%pi - k*%pi else %pi + k*%pi)
                  else (if s = 1 then %pi + k*%pi else %pi - k*%pi);
wrong_deg: ta*180/%pi;
wrong_sign: if fn = 1 then -k*%pi else -ta;
